    {
      "name": "齐鲁工业大学（山东省科学院）",
      "reason": "位于济南，计算机科学与技术学部开设计算机科学与技术、网络空间安全、计算机技术等硕士方向；2027年招生目录显示相关专业初试可按思想政治理论、英语、数学和408计算机学科专业基础准备，和计算机网络技术本科背景衔接较直接。计算机类教科研机构分布于长清、彩石、千佛山等济南校区，主校区在长清。未来2030年目录、科目和实际培养校区待核实。",
      "sourceUrl": "https://yjszs.qlu.edu.cn/2026/0930/c6601a284168/page.htm#6#1",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "计算机科学与技术学部相关教科研机构分布在长清、彩石、千佛山校区，均在济南；主校区为长清校区，具体培养校区以当年安排为准。",
        "sourceUrl": "https://zsb.qlu.edu.cn/home/article/faq_details/65"
      },
      "criteriaEvidence": [
        {
          "criterion": "历史一本",
          "explanation": "官方年度资料显示，2024年该校在山西、内蒙古、河南、四川、云南5个未实行新高考改革的省份一本批次招生；该记录仅适用于上述省份和2024年，山东省已合并批次，不能据此推断2030年报考资格。",
          "sourceUrl": "https://xxgk.qlu.edu.cn/_upload/article/files/74/01/f840e5e940f68c52cd627a99041a/78b153b7-de52-4856-896b-4755d5683ee9.pdf#8#2"
        }
      ]
    },
    {
      "name": "山东师范大学",
      "reason": "位于济南，信息科学与工程学院开设计算机科学与技术、计算机技术、软件工程、人工智能等硕士方向，2026年相关初试科目涉及数据结构或计算机学科专业基础，适合计算机类本科继续深造。2027年招生章程显示信息科学与工程学院在长清湖校区，校区仍在济南。2030年目录、科目、招生计划和实际培养地点待核实。",
      "sourceUrl": "https://www.yjszs.sdnu.edu.cn/system/resource/pdfjs/viewer.html?file=%2F__local%2F8%2FC1%2F90%2F6486FCB6BEE008D2F23F41BC4E3_846DC92C_2C34B.pdf&_x_output_type_b6db407c4_=embedded_pdf#2#2",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "信息科学与工程学院等多数招生学院在长清湖校区，位于济南；教育学部等部分学院在千佛山校区。计算机相关专业实际培养校区以当年安排为准。",
        "sourceUrl": "http://www.yjszs.sdnu.edu.cn/info/1009/5325.htm#2"
      },
      "criteriaEvidence": [
        {
          "criterion": "历史一本",
          "explanation": "学校官方2016年省外普通专业录取统计列有河北本科一批、天津本科一批B类，可作为历史一本参考层次；该记录仅适用于2016年相应省份和普通专业，不能泛称所有省份、所有专业或未来年度均为一本。",
          "sourceUrl": "https://cie.sdnu.edu.cn/info/1072/1924.htm"
        }
      ]
    },
    {
      "name": "济南大学",
      "reason": "位于济南，信息科学与工程学院开设计算机科学与技术、计算机技术、人工智能等硕士方向，计算机科学与技术本科办学历史较长并有相应硕士点，专业匹配度较高。学校招生资料显示信息科学与工程学院在主校区，地址在济南市南辛庄西路。2030年招生目录、初试科目、招生条件和培养地点待核实。",
      "sourceUrl": "http://yz.ujn.edu.cn/info/1032/3214.htm#1",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "信息科学与工程学院在主校区，位于济南市南辛庄西路336号；学校已公布校区均在济南，具体培养地点以当年安排为准。",
        "sourceUrl": "https://admission.ujn.edu.cn/info/1024/2532.htm?_x_output_type_b6db407c4_=embedded_pdf#2#1"
      },
      "criteriaEvidence": [
        {
          "criterion": "历史一本",
          "explanation": "学校官方2016年全国各省普通文理录取分数线列有山东普通本科一批次及济南走读本科一批次，可作为2016年山东省内历史一本参考；不表示所有项目、所有省份或此后各年均为同一批次，山东已合并批次，未来要求待核实。",
          "sourceUrl": "https://xxgk.ujn.edu.cn/__local/2/D4/61/18EB3CE24CAB055ADA7C69E792C_BBC62789_218FF.pdf#2#1"
        }
      ]
    }
  ],
  "tasks": [
    {
      "title": "建立考研信息档案：核对本科培养方案、英语与数学课程安排，记录济南地区计算机类院校官网和研招网入口，明确2029年初试为暂定节点。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-07"
    },
    {
      "title": "英语基础补弱：坚持词汇与语法训练，完成四级核心词汇一轮，开始每周精读一篇计算机科普或校园英文材料。",
      "stage": "信息核对与基础",
      "dueDate": "2026-12-24"
    },
    {
      "title": "数学基础起步：跟完高等数学上册基础内容，整理极限、导数、积分错题，保持每周固定习题量。",
      "stage": "信息核对与基础",
      "dueDate": "2027-03-11"
    },
    {
      "title": "专业基础探索：学好C语言与数据结构先修内容，了解计算机组成、操作系统、计算机网络四门核心课的学习顺序。",
      "stage": "信息核对与基础",
      "dueDate": "2027-05-28"
    },
    {
      "title": "数学一轮推进：完成高等数学与线性代数基础复习，建立章节框架，开始概率论基础。",
      "stage": "系统学习与强化",
      "dueDate": "2027-08-13"
    },
    {
      "title": "英语持续积累：扩大考研词汇量，练习长难句，开始每周两篇阅读精练并整理生词。",
      "stage": "系统学习与强化",
      "dueDate": "2027-10-30"
    },
    {
      "title": "专业核心课强化：系统学习数据结构与计算机组成原理，配合课后题理解基本概念和算法。",
      "stage": "系统学习与强化",
      "dueDate": "2028-01-16"
    },
    {
      "title": "专业核心课强化：学习操作系统与计算机网络，整理常见模型、协议和典型计算题。",
      "stage": "系统学习与强化",
      "dueDate": "2028-04-02"
    },
    {
      "title": "数学强化与真题入门：完成数学第二轮复习，按章节做真题基础题，归纳常错题型。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-06-19"
    },
    {
      "title": "英语真题训练：开始近十年阅读真题，分析出题思路，同步准备翻译和新题型。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-09-04"
    },
    {
      "title": "专业课真题与408或自命题科目核对：根据目标院校当年目录确认考试科目，完成一轮专业课真题并查漏。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-11-21"
    },
    {
      "title": "寒假查漏补缺：针对数学、英语、专业课薄弱章节做专项训练，关注目标院校最新招生宣讲与目录预告。",
      "stage": "真题训练与查漏",
      "dueDate": "2029-02-07"
    },
    {
      "title": "春季强化收尾：完成专业课第二轮和数学错题复盘，英语保持阅读与写作训练。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-04-25"
    },
    {
      "title": "暑期强化：进入全天节奏，数学、专业课、英语、政治按比例推进，整理框架笔记和易错点。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-07-12"
    },
    {
      "title": "真题模拟与报名准备：按套卷训练，核对预报名、报考点、招生简章和考试科目，确认待核实信息。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-09-27"
    },
    {
      "title": "冲刺调整：回顾错题、公式、专业课框架和英语作文模板，调整作息，按暂定考试季节奏保持手感；正式初试日期以官方通知为准。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-12-14"
    }
  ]
}

